cases.bad:
// PageScanner observer fire trước → PAGE_SCAN_RESULT add 27 subtitles
// EpisodeChangeWatcher fire sau → VIDEO_EPISODE_CHANGED clearTab wipe 27
// Net effect: 0 subtitles (clear wipe add)
void sendMessage({ type: VIDEO_EPISODE_CHANGED, payload });
void sendMessage({ type: PAGE_SCAN_RESULT, payload: scan() }); // fire-and-forget, order không guaranteed

cases.good:
// Await clear (VIDEO_EPISODE_CHANGED) trước, rồi re-scan + re-send add
void sendMessage({ type: VIDEO_EPISODE_CHANGED, payload }).then(() => {
  // clear processed → re-scan + re-send PAGE_SCAN_RESULT → add SAU clear
  const urls = scanner.scan();
  if (urls.videoUrls.length || urls.subtitleUrls.length) {
    void sendMessage({ type: PAGE_SCAN_RESULT, payload: { videoUrls: urls.videoUrls, subtitleUrls: urls.subtitleUrls } });
  }
});
// re-scan idempotent: dedup by URL trong handleRequest
